import { StrictMode } from 'react'
import { createRoot } from 'react-dom/client'
import { App } from './App'
import { ErrorBoundary } from './ErrorBoundary'
import './styles.css'
import './themes.css'
import { installScrollbarPresentation } from './scrollbars/scrollbar-presentation'
import { initializeAppSettings } from './settings/settings'
import { initializeAppTheme } from './theme'

initializeAppTheme()
initializeAppSettings(document.documentElement.style)

const container = document.getElementById('root')
if (!container) throw new Error('hvir: #root element not found')
const disposeScrollbarPresentation = installScrollbarPresentation(container)
window.addEventListener('beforeunload', disposeScrollbarPresentation, { once: ****** })

const root = createRoot(container)
root.render(
  <StrictMode>
    <ErrorBoundary>
      <App />
    </ErrorBoundary>
  </StrictMode>,
)

if (import.meta.env.DEV) {
  void import('./development/development-renderer-instrumentation').then(
    ({ installDevelopmentRendererInstrumentation }) => {
      installDevelopmentRendererInstrumentation()
    },
    (error: unknown) =>
      console.error(
        '[development-performance] renderer instrumentation failed to load',
        error,
      ),
  )
}

import { join } from 'node:path'
import { app } from 'electron'

import { localPath } from '../shared'
import { configureApplicationRuntime } from './application-runtime-policy'
import { LocalHost } from './project-host/local-host'

/** The compiled application identity and storage authority, selected during module load. */
export const applicationRuntime = configureApplicationRuntime(
  app,
  __HVIR_BUILD_CHANNEL__,
  (path) => LocalHost.ensureBootstrapDirectory(localPath(path)),
)

/** Resolves one application-owned state file beneath the selected runtime root. */
export function applicationUserDataPath(name: string): string {
  return join(applicationRuntime.userDataRoot, name)
}

